INSERT INTO roles (code, name, description, is_system) SELECT 'super_admin', 'Super Admin', 'Full access. Sameer Bhaiya. Cannot be edited or deleted.', true WHERE NOT EXISTS (SELECT 1 FROM roles WHERE code = 'super_admin' AND deleted_at IS NULL);
INSERT INTO roles (code, name, description, is_system) SELECT 'operations_admin', 'Operations Admin', 'Runs day-to-day marketplace data: masters, teachers, institutes, users, leads, CMS.', true WHERE NOT EXISTS (SELECT 1 FROM roles WHERE code = 'operations_admin' AND deleted_at IS NULL);
INSERT INTO roles (code, name, description, is_system) SELECT 'verification_admin', 'Verification Admin', 'Reviews teacher and institute documents, evaluates institutes, watches trust scores.', true WHERE NOT EXISTS (SELECT 1 FROM roles WHERE code = 'verification_admin' AND deleted_at IS NULL);
INSERT INTO roles (code, name, description, is_system) SELECT 'finance_admin', 'Finance Admin', 'Owns pricing, payments, refunds, subscriptions and referral rewards.', true WHERE NOT EXISTS (SELECT 1 FROM roles WHERE code = 'finance_admin' AND deleted_at IS NULL);
INSERT INTO roles (code, name, description, is_system) SELECT 'support_admin', 'Support Admin', 'Handles reviews, complaints and user support.', true WHERE NOT EXISTS (SELECT 1 FROM roles WHERE code = 'support_admin' AND deleted_at IS NULL);
